    def _resolve_user_timezone_name(
        self,
        user: User,
        *,
        timezone_name: str | None = None,
    ) -> str:
        profile = getattr(user, "profile", None)
        candidates = [
            getattr(profile, "timezone", None),
            timezone_name,
            django_settings.TIME_ZONE,
        ]
        for candidate in candidates:
            normalized = str(candidate or "").strip()
            if not normalized:
                continue
            try:
                ZoneInfo(normalized)
            except ZoneInfoNotFoundError:
                continue
            return normalized
        return "UTC"

    def prepare_medication_tasks(
        self,
        family: FamilyGroup,
        *,
        user: User,
        medications: list[dict[str, Any]] | None = None,
        raw_text: str = "",
        care_subject_type: str | None = None,
        care_subject_id: str | None = None,
        care_subject_name: str | None = None,
        inbox_capture_id: str | None = None,
        now: str | None = None,
        timezone_name: str | None = None,
        **_: Any,
    ) -> dict[str, Any]:
        resolved_timezone_name = self._resolve_user_timezone_name(
            user,
            timezone_name=timezone_name,
        )
        request_timezone = ZoneInfo(resolved_timezone_name)
        parsed_now = parse_datetime(now) if now else None
        if parsed_now is not None and timezone.is_naive(parsed_now):
            parsed_now = parsed_now.replace(tzinfo=request_timezone)
        elif parsed_now is not None:
            parsed_now = parsed_now.astimezone(request_timezone)
        bundle: dict[str, Any] | None = None
        if inbox_capture_id:
            capture = InboxCapture.objects.filter(
                id=inbox_capture_id,
                family=family,
            ).first()
            if capture is None:
                return {
                    "ok": False,
                    "proposal_ready": False,
                    "error": "Inbox capture not found.",
                }
            normalized_payload = capture.normalized_payload or {}
            if normalized_payload.get("kind") == "medication_task_bundle":
                bundle = dict(normalized_payload)
                bundle["source"] = "clancy"
                bundle["source_capture_id"] = str(capture.id)
                bundle.setdefault("timezone", resolved_timezone_name)
        if bundle is None:
            bundle = prepare_medication_task_bundle(
                family=family,
                created_by=user,
                source="clancy",
                extracted={
                    "raw_text": raw_text,
                    "medications": medications or [],
                    "care_subject_type": care_subject_type,
                    "care_subject_id": care_subject_id,
                    "care_subject_name": care_subject_name,
                },
                care_subject_type=care_subject_type,
                care_subject_id=care_subject_id,
                care_subject_name=care_subject_name,
                now=parsed_now,
                timezone_name=resolved_timezone_name,
            )
        return {
            "ok": True,
            "proposal_ready": bool(bundle["task_drafts"]),
            "proposal_type": FamilyAgentProposal.Type.FAMILY_TASK_OCCURRENCES,
            "summary": "Create medication tasks",
            "preview_text": bundle["preview_text"],
            "payload_json": bundle,
        }

