                message__thread=thread,
                kind=FamilyAgentMessageAttachment.Kind.IMAGE,
                analysis_status=FamilyAgentMessageAttachment.AnalysisStatus.COMPLETED,
            )
            .select_related("message")
            .order_by("-message__created_at", "-display_order")[:limit]
        )
        attachments.reverse()
        return [
            {
                "id": str(attachment.id),
                "message_id": str(attachment.message_id),
                "message_created_at": attachment.message.created_at.isoformat(),
                "original_filename": attachment.original_filename,
                "analysis": attachment.analysis_json or {},
            }
            for attachment in attachments
        ]

    def build_runtime_context(
        self,
        *,
        user: User,
        family: FamilyGroup,
        thread: FamilyAgentThread | None,
        trigger_message: FamilyAgentMessage | None,
        message_text: str,
        context_payload: dict[str, Any],
    ) -> dict[str, Any]:
        source_screen = self._normalize_text(
            (context_payload or {}).get("source_screen")
        )
        active_group = None
        active_group_id = str((context_payload or {}).get("group_id") or "").strip()
        if active_group_id:
            accessible_group = self._get_accessible_group(user, active_group_id)
            if accessible_group is not None:
                active_group = self._read_active_group_summary(accessible_group)

        focused_event: dict[str, Any] | None = None
        focused_event_id = str((context_payload or {}).get("event_id") or "").strip()
        if focused_event_id:
            details = self.get_event_details(
                family=family, user=user, event_ids=[focused_event_id]
            )
            if details:
                focused_event = details[0]

        focused_capture: dict[str, Any] | None = None
        focused_capture_id = coerce_uuid((context_payload or {}).get("capture_id"))
        if focused_capture_id is not None:
            capture = (
                InboxCapture.objects.filter(id=focused_capture_id, family=family)
                .only(
                    "id",
                    "capture_type",
                    "status",
                    "raw_text",
                    "source_email",
                    "source_client_app",
                    "normalized_payload",
                )
                .first()
            )
            if capture is not None:
                payload = capture.normalized_payload or {}
                focused_capture = {
                    "id": str(capture.id),
                    "capture_type": capture.capture_type,
                    "status": capture.status,
                    "source_client_app": capture.source_client_app,
                    "source_kind": self._normalize_text(payload.get("source_kind")),
                    "source_url": self._normalize_text(payload.get("source_url")),
                    "source_domain": self._normalize_text(payload.get("source_domain")),
                    "preview_title": self._normalize_text(payload.get("preview_title")),
                    "preview_text": self._normalize_text(payload.get("preview_text")),
                    "preview_price_text": self._normalize_text(
                        payload.get("preview_price_text")
                    ),
                    "thumbnail_ref": self._normalize_text(payload.get("thumbnail_ref"))
                    or None,
                    "captured_from": self._normalize_text(payload.get("captured_from")),
                }
                if source_screen == "inbox_review":
                    focused_capture.update(
                        {
                            "source_email": self._normalize_text(capture.source_email),
                            "raw_text": self._normalize_text(capture.raw_text)[:4000],
                            "preview_text": get_capture_preview_text(capture),
                            "classification": self._normalize_text(
                                payload.get("classification")
                            ),
                            "review_proposals": get_capture_proposals(capture),
                        }
                    )

        task_snapshot: dict[str, Any] | None = None
        list_snapshot: dict[str, Any] | None = None
        chore_snapshot: dict[str, Any] | None = None
        if source_screen == "today":
            task_snapshot = self.summarize_task_board(family, user=user)
            grocery_lists = self.list_grocery_lists(
                family,
                user=user,
                limit=5,
            )
            chore_programs = self.list_chore_programs(
                family,
                user=user,
                active_only=True,
                limit=5,
            )
            list_snapshot = {
                "list_count": grocery_lists["count"],
                "recent_lists": grocery_lists["lists"],
            }
            chore_snapshot = {
                "active_program_count": chore_programs["count"],
                "active_programs": chore_programs["programs"],
            }

        context = {
            "family": self.read_current_family_summary(family, user=user),
            "accessible_groups": self.read_accessible_groups_summary(user),
            "active_group": active_group,
            "external_calendars": self.read_connected_external_calendar_summaries(
                family
            ),
            "focused_event": focused_event,
            "focused_capture": focused_capture,
            "task_snapshot": task_snapshot,
            "list_snapshot": list_snapshot,
            "chore_snapshot": chore_snapshot,
            "events": self.read_current_family_calendar_events(family),
            "tentative_shares": self.read_tentative_share_summaries(family),
            "trips": self.read_trip_summaries(family, user=user),
            "memory": self.read_family_memory(family),
            "recent_messages": (
                self.read_recent_thread_messages(thread) if thread is not None else []
            ),
            "current_message_attachments": self.read_message_attachments(
                trigger_message
            ),
            "current_message_attachment_summary": self.summarize_message_attachments(
                trigger_message
            ),
            "recent_image_attachments": (
                self.read_recent_image_attachments(thread) if thread is not None else []
            ),
            "request_context": context_payload or {},
            "latest_user_message": message_text,
        }
        return _apply_context_size_budget(
            context,
            max_chars=int(
                getattr(django_settings, "FAMILY_AGENT_CONTEXT_MAX_CHARS", 200_000)
            ),
        )

    def preview_external_calendar_connection(
        self,
        ical_url: str,
        account_name: str | None = None,
        *,
        user: User,
        **_: Any,
    ) -> dict[str, Any]:
        preview = preview_ics_calendar_subscription(
