            "source_host": preview["source_host"],
            "metadata": preview.get("metadata") or {},
            "already_connected": bool(preview.get("already_connected")),
            "calendar_id": preview.get("calendar_id"),
        }

    def resolve_scheduling_link(
        self,
        source_url: str,
        invitee_name: str | None = None,
        invitee_email: str | None = None,
        invitee_timezone: str | None = None,
        *,
        user: User,
        family: FamilyGroup,
        **_: Any,
    ) -> dict[str, Any]:
        return self.scheduling_provider.resolve_link(
            source_url,
            family=family,
            user=user,
            invitee_name=invitee_name,
            invitee_email=invitee_email,
            invitee_timezone=invitee_timezone,
        )

    def list_scheduling_slots(
        self,
        source_url: str,
        start_time: str,
        end_time: str,
        invitee_name: str | None = None,
        invitee_email: str | None = None,
        invitee_timezone: str | None = None,
        *,
        user: User,
        family: FamilyGroup,
        **_: Any,
    ) -> dict[str, Any]:
        resolution = self.resolve_scheduling_link(
            source_url,
            invitee_name=invitee_name,
            invitee_email=invitee_email,
            invitee_timezone=invitee_timezone,
            user=user,
            family=family,
        )
        parsed_start = parse_datetime(start_time)
        parsed_end = parse_datetime(end_time)
        if parsed_start is None or parsed_end is None:
            raise ValueError("Scheduling slot windows require ISO datetimes.")
        slots = self.scheduling_provider.list_available_slots(
            resolution=resolution,
            start_time=parsed_start,
            end_time=parsed_end,
        )
        return {**resolution, "available_slots": slots}

    def prepare_scheduling_booking(
        self,
        source_url: str,
        selected_slot_start: str | None = None,
        event_type_uri: str | None = None,
        invitee_name: str | None = None,
        invitee_email: str | None = None,
        invitee_timezone: str | None = None,
        guest_emails: list[str] | None = None,
        *,
        user: User,
        family: FamilyGroup,
        **_: Any,
    ) -> dict[str, Any]:
        resolution = self.resolve_scheduling_link(
            source_url,
            invitee_name=invitee_name,
            invitee_email=invitee_email,
            invitee_timezone=invitee_timezone,
            user=user,
            family=family,
        )
        if not resolution.get("api_available"):
            return {
                **resolution,
                "proposal_ready": False,
                "action_suggestion": {
                    "type": "external_scheduling_handoff",
                    "title": "Open Calendly",
                    "label": "Finish in Calendly",
                    "url": resolution["handoff_url"],
                },
            }
        if not selected_slot_start:
            return {**resolution, "proposal_ready": False}
        return {
            **resolution,
            "proposal_ready": True,
            "proposal_type": FamilyAgentProposal.Type.EXTERNAL_SCHEDULING_BOOKING,
            "payload_json": {
                "provider": resolution["provider"],
                "source_url": source_url,
                "event_type_uri": event_type_uri or resolution.get("event_type_uri"),
                "selected_slot_start": selected_slot_start,
                "invitee": {
                    "name": invitee_name,
                    "email": invitee_email,
                    "timezone": invitee_timezone,
                },
                "guest_emails": guest_emails or [],
            },
        }

    def commit_approved_proposal(
        self,
        proposal: FamilyAgentProposal,
        *,
        approved_by: User,
    ) -> dict[str, Any]:
        proposal_type = normalize_family_agent_proposal_type(proposal.proposal_type)
        if proposal_type is None:
            raise ValueError(f"Unsupported proposal type: {proposal.proposal_type}")
        if self._is_group_plan_proposal_type(proposal_type):
            return self._commit_group_plan(proposal, approved_by=approved_by)
        if proposal_type == FamilyAgentProposal.Type.TENTATIVE_EVENT:
            return self._commit_tentative_event(proposal, approved_by=approved_by)
        if proposal_type == FamilyAgentProposal.Type.SHARE_TENTATIVE_EVENT:
            return self._commit_share_tentative_event(proposal, approved_by=approved_by)
        if proposal_type == FamilyAgentProposal.Type.CONFIRM_TENTATIVE_EVENT:
            return self._commit_confirm_tentative_event(
                proposal, approved_by=approved_by
            )
        if proposal_type == FamilyAgentProposal.Type.TRIP_EVENT:
            return self._commit_trip_event(proposal, approved_by=approved_by)
        if proposal_type == FamilyAgentProposal.Type.TRIP_INVITE:
            return self._commit_trip_invite(proposal, approved_by=approved_by)
        if proposal_type == FamilyAgentProposal.Type.FAMILY_LIST_ITEMS:
            return self._commit_family_list_items(proposal, approved_by=approved_by)
        if proposal_type == FamilyAgentProposal.Type.FAMILY_TASK_OCCURRENCES:
            return self._commit_family_task_occurrences(
                proposal,
                approved_by=approved_by,
            )
        if proposal_type == FamilyAgentProposal.Type.EXTERNAL_CALENDAR_CONNECT:
            return self._commit_external_calendar_connect(
                proposal, approved_by=approved_by
            )
        if proposal_type == FamilyAgentProposal.Type.EXTERNAL_SCHEDULING_BOOKING:
            return self._commit_external_scheduling_booking(
                proposal, approved_by=approved_by
            )
        raise ValueError(f"Unsupported proposal type: {proposal.proposal_type}")

    def _commit_family_task_occurrences(
        self, proposal: FamilyAgentProposal, *, approved_by: User
    ) -> dict[str, Any]:
        payload = proposal.payload_json or {}
        if not isinstance(payload, dict):
            raise ValueError("Family task occurrence proposals require a payload.")
        source_capture_id = str(
            payload.get("source_capture_id") or payload.get("inbox_capture_id") or ""
        ).strip()
        if source_capture_id:
            capture = InboxCapture.objects.filter(
                id=source_capture_id,
                family=proposal.thread.family,
            ).first()
            if capture is None:
                raise ValueError("Source inbox capture was not found.")
            tasks = create_tasks_from_capture(
                capture,
                reviewed_tasks=[
                    task
                    for task in payload.get("task_drafts", [])
                    if isinstance(task, dict)
                ],
            )
            return {
                "task_ids": [str(task.id) for task in tasks],
                "series_ids": [
                    str(task.task_series_id)
                    for task in tasks
                    if task.task_series_id is not None
                ],
                "created_count": len(tasks),
            }
        flat_tasks = payload.get("tasks")
        if (
            flat_tasks is None
            and not payload.get("medications")
            and not payload.get("task_drafts")
            and str(payload.get("title") or "").strip()
        ):
            flat_tasks = [payload]
        if isinstance(flat_tasks, list) and not payload.get("medications"):
            task_drafts = [
                draft
                for draft in flat_tasks
                if isinstance(draft, dict) and str(draft.get("title") or "").strip()
            ]
            if not task_drafts:
                raise ValueError(
                    "Proposal payload tasks list is empty or missing titles."
                )
            created_tasks: list[FamilyTask] = []
            for draft in task_drafts:
                due_at_value = draft.get("starts_at") or draft.get("due_at")
                due_at = (
                    self._parse_event_datetime(due_at_value, field_name="starts_at")
                    if due_at_value
                    else None
                )
                created_tasks.append(
                    create_task_from_household_action(
                        family=proposal.thread.family,
                        title=str(draft["title"]).strip(),
                        notes=str(draft.get("notes") or "").strip(),
                        due_at=due_at,
                        source_client_app="organize",
                        created_by=approved_by,
                        source_object=proposal,
                    )
                )
            return {
                "task_ids": [str(task.id) for task in created_tasks],
                "series_ids": [],
                "created_count": len(created_tasks),
            }
        if not payload.get("medications") and not payload.get("task_drafts"):
            raise ValueError(
                "Family task occurrence proposal payload missing source_capture_id, "
                "tasks list, or medication bundle."
            )
        medications_payload = payload.get("medications") or []
        task_drafts_payload = payload.get("task_drafts") or []
        has_named_medication = any(
            isinstance(med, dict) and str(med.get("medication_name") or "").strip()
            for med in medications_payload
        )
        has_selectable_draft = any(
            isinstance(draft, dict)
            and str(draft.get("title") or "").strip()
            and draft.get("selected", True)
            for draft in task_drafts_payload
        )
        if not has_named_medication and not has_selectable_draft:
            raise ValueError(
                "Medication details missing from this proposal. Re-share the "
                "medication photo or list the meds in chat so Clancy can build a "
                "complete schedule."
            )
        bundle_payload: dict[str, Any] = payload
        if has_named_medication and not has_selectable_draft:
            care_subject = (
                payload.get("care_subject")
                if isinstance(payload.get("care_subject"), dict)
                else {}
            )
            rebuilt_bundle = prepare_medication_task_bundle(
                family=proposal.thread.family,
                created_by=approved_by,
                source=str(payload.get("source") or "clancy"),
                extracted={
                    "raw_text": str(payload.get("raw_text") or ""),
                    "medications": medications_payload,
                    "care_subject_type": (
                        care_subject.get("type") or payload.get("care_subject_type")
                    ),
                    "care_subject_id": (
                        care_subject.get("id") or payload.get("care_subject_id")
                    ),
                    "care_subject_name": (
                        care_subject.get("name") or payload.get("care_subject_name")
                    ),
                },
                care_subject_type=care_subject.get("type"),
                care_subject_id=care_subject.get("id"),
                care_subject_name=care_subject.get("name"),
                timezone_name=(
                    str(payload.get("timezone") or payload.get("timezone_name") or "")
                    or None
                ),
            )
            if not rebuilt_bundle.get("task_drafts"):
                raise ValueError(
                    "Could not build medication schedule drafts from the proposal. "
                    "Re-share the medication photo or list the meds in chat."
                )
            bundle_payload = rebuilt_bundle
        _series, tasks = materialize_medication_task_bundle(
            family=proposal.thread.family,
            created_by=approved_by,
            bundle=bundle_payload,
            source_client_app="organize",
            source_object=proposal,
            default_reminder_recipient=approved_by,
        )
        return {
            "task_ids": [str(task.id) for task in tasks],
            "series_ids": [
                str(task.task_series_id)
                for task in tasks
                if task.task_series_id is not None
            ],
            "created_count": len(tasks),
        }

    def _commit_external_scheduling_booking(
        self, proposal: FamilyAgentProposal, *, approved_by: User
    ) -> dict[str, Any]:
        payload = proposal.payload_json or {}
        if not isinstance(payload, dict):
            raise ValueError("Scheduling booking proposals require a payload.")
        return self.scheduling_provider.create_booking(
            family=proposal.thread.family,
            user=approved_by,
            payload=payload,
        )

    def _commit_external_calendar_connect(
        self, proposal: FamilyAgentProposal, *, approved_by: User
    ) -> dict[str, Any]:
        payload = proposal.payload_json or {}
        ical_url = payload.get("ical_url")
        if not ical_url:
            raise ValueError("External calendar connect proposals require an ical_url.")

        account_name = payload.get("account_name")
        metadata = (
            payload.get("metadata")
            if isinstance(payload.get("metadata"), dict)
            else None
        )

        calendar, created = create_or_get_ics_calendar_subscription(
            user=approved_by,
            ical_url=ical_url,
            account_name=account_name,
            metadata=metadata,
        )
        return {
            "calendar_id": str(calendar.id),
            "account_name": calendar.account_name,
            "ical_url": calendar.ical_url,
            "created": created,
        }

    def _commit_tentative_event(
        self, proposal: FamilyAgentProposal, *, approved_by: User
    ) -> dict[str, Any]:
        payload = proposal.payload_json or {}
        start_time = self._parse_event_datetime(
            payload.get("start_time"), field_name="start_time"
        )
        end_time = self._parse_event_datetime(
            payload.get("end_time"), field_name="end_time"
        )

        event = Event.objects.create(
            title=payload.get("title", proposal.summary),
            description=payload.get("description", ""),
            location=payload.get("location", ""),
            start_time=start_time,
            end_time=end_time,
            creator=approved_by,
            family_group=proposal.thread.family,
            visibility=payload.get("visibility", "PUBLIC"),
            event_status=Event.STATUS_TENTATIVE,
        )
        return {"event_id": str(event.id), "event_status": event.event_status}

    def _commit_share_tentative_event(
        self, proposal: FamilyAgentProposal, *, approved_by: User
    ) -> dict[str, Any]:
        payload = proposal.payload_json or {}
        event_id = payload.get("event_id")
        if not event_id:
            raise ValueError("Share proposals require an event_id.")

        event = Event.objects.get(id=event_id, family_group=proposal.thread.family)
        if event.event_status != Event.STATUS_TENTATIVE:
            raise ValueError("Only tentative events can be shared.")

        source_family = proposal.thread.family
        user_family_ids = {source_family.id}
        meta_family_ids = list(
            MetaFamilyMembership.objects.filter(
                family_id__in=user_family_ids
            ).values_list("meta_family_id", flat=True)
        )
        network_family_ids = (
            set(
                MetaFamilyMembership.objects.filter(
                    meta_family_id__in=meta_family_ids
                ).values_list("family_id", flat=True)
            )
            - user_family_ids
        )

        target_family_ids = {
            str(family_id) for family_id in payload.get("target_family_ids", [])
        }
        invalid_ids = target_family_ids - {
            str(family_id) for family_id in network_family_ids
        }
        if invalid_ids:
            raise ValueError("Some target families are not in the current network.")

        created_shares: list[str] = []
        for target_family_id in target_family_ids:
            share, created = TentativeEventShare.objects.get_or_create(
                event=event,
                target_family_id=UUID(target_family_id),
                defaults={
                    "shared_by": approved_by,
                    "source_family": source_family,
                    "message": payload.get("message", ""),
                },
            )
            if created:
                created_shares.append(str(share.id))

        return {"event_id": str(event.id), "share_ids": created_shares}

    def _commit_confirm_tentative_event(
        self, proposal: FamilyAgentProposal, *, approved_by: User
    ) -> dict[str, Any]:
        payload = proposal.payload_json or {}
        event_id = payload.get("event_id")
        if not event_id:
            raise ValueError("Confirm proposals require an event_id.")

        event = Event.objects.get(id=event_id, family_group=proposal.thread.family)
        if event.event_status != Event.STATUS_TENTATIVE:
            raise ValueError("Only tentative events can be confirmed.")

        event.event_status = Event.STATUS_CONFIRMED
        event.creator = approved_by
        event.save(update_fields=["event_status", "creator", "updated_at"])
        return {"event_id": str(event.id), "event_status": event.event_status}

    def _commit_trip_event(
        self, proposal: FamilyAgentProposal, *, approved_by: User
    ) -> dict[str, Any]:
        payload = proposal.payload_json or {}
        trip_id = payload.get("trip_id")
        if not trip_id:
            raise ValueError("Trip event proposals require a trip_id.")
        trip = Trip.objects.get(id=trip_id)
        if not TripFamilyGroups.objects.filter(
            trip=trip,
            familygroup=proposal.thread.family,
        ).exists():
            raise ValueError("Current family does not have access to that trip.")

        start_time = self._parse_event_datetime(
            payload.get("start_time"), field_name="start_time"
        )
        end_time = self._parse_event_datetime(
            payload.get("end_time"), field_name="end_time"
        )

        event = Event.objects.create(
            title=payload.get("title", proposal.summary),
            description=payload.get("description", ""),
            location=payload.get("location", trip.location),
            start_time=start_time,
            end_time=end_time,
            creator=approved_by,
            family_group=proposal.thread.family,
            internal_calendar=trip.internal_calendar,
            visibility=payload.get("visibility", "PUBLIC"),
            event_status=payload.get("event_status", Event.STATUS_CONFIRMED),
        )
        return {"event_id": str(event.id), "trip_id": str(trip.id)}

    def _commit_trip_invite(
        self, proposal: FamilyAgentProposal, *, approved_by: User
    ) -> dict[str, Any]:
        payload = proposal.payload_json or {}
        trip_id = payload.get("trip_id")
        invited_family_id = payload.get("invited_family_id")
        if not trip_id or not invited_family_id:
            raise ValueError(
                "Trip invite proposals require trip_id and invited_family_id."
            )
        trip = Trip.objects.get(id=trip_id)
        invited_family = FamilyGroup.objects.get(id=invited_family_id)
        inviting_family = proposal.thread.family

        if invited_family == inviting_family:
            raise ValueError("Cannot invite your own family.")

        if not TripFamilyGroups.objects.filter(
            trip=trip,
            familygroup=inviting_family,
            status=TripFamilyGroups.STATUS_ACCEPTED,
        ).exists():
            raise ValueError("Current family must already be accepted on the trip.")

        with transaction.atomic():
            invite = TripInvite.objects.create(
                trip=trip,
                inviting_family=inviting_family,
                invited_family=invited_family,
                inviting_user=approved_by,
                nickname=payload.get("nickname"),
            )
            self.participation_resolver.invite_family(
                trip,
                invited_family,
                invited_by=approved_by,
                inviting_family=inviting_family,
                source=TripFamilyGroups.SOURCE_DIRECT,
                source_invite=invite,
            )

        FamilyFeatureSettings.enable_feature_for_family(invited_family, "trips")

        return {
            "trip_id": str(trip.id),
            "invite_id": str(invite.id),
            "invited_family_id": str(invited_family.id),
        }

    def _commit_family_list_items(
        self, proposal: FamilyAgentProposal, *, approved_by: User
    ) -> dict[str, Any]:
        payload = proposal.payload_json or {}
        family_list = self._resolve_family_list_for_proposal(
            proposal,
            approved_by=approved_by,
        )
        item_payloads = self._normalize_family_list_item_payloads(payload)
        max_position = (
            family_list.items.aggregate(max_position=models.Max("position"))[
                "max_position"
            ]
            or 0
        )

        with transaction.atomic():
            created_items = [
                GroceryItem.objects.create(
                    grocery_list=family_list,
                    name=item_payload["name"],
                    quantity=item_payload["quantity"],
                    unit=item_payload["unit"],
                    position=max_position + index,
                    created_by=approved_by,
                )
                for index, item_payload in enumerate(item_payloads, start=1)
            ]

        return {
            "family_list_id": str(family_list.id),
            "grocery_list_id": str(family_list.id),
            "item_ids": [str(item.id) for item in created_items],
            "created_count": len(created_items),
        }

    def _commit_group_plan(
        self, proposal: FamilyAgentProposal, *, approved_by: User
    ) -> dict[str, Any]:
        payload = self.normalize_family_network_group_plan_payload(
            proposal.payload_json or {},
            context_group_id=self._get_proposal_context_group_id(proposal),
            summary=proposal.summary,
            preview_text=proposal.preview_text,
        )
        group_id = str(payload.get("group_id") or "").strip()
        if not group_id:
            raise ValueError("Group plan proposals require a group_id.")

        target_group = FamilyGroup.objects.filter(id=group_id).first()
        if target_group is None:
            raise ValueError("Group plan target group was not found.")

        if self._get_group_kind(target_group) != "META":
            raise ValueError("Group plan target must be a META network.")

        if not MetaFamilyMembership.objects.filter(
            family=proposal.thread.family,
            meta_family=target_group,
        ).exists():
            raise ValueError("Current family does not have access to that network.")

        mode = self._normalize_group_plan_mode(payload.get("mode"))

        template = self._normalize_group_plan_template(payload.get("template"))

        raw_plan_options = payload.get("plan_options")
        if not isinstance(raw_plan_options, list) or not raw_plan_options:
            raise ValueError("Group plan proposals require at least one plan option.")

        plan_option_payloads: list[dict[str, Any]] = []
        for option in raw_plan_options:
            if not isinstance(option, dict):
                raise ValueError("Group plan options must be objects.")

            start_time = self._parse_event_datetime(
                option.get("start_time"), field_name="start_time"
            )
            end_time = self._parse_event_datetime(
                option.get("end_time"), field_name="end_time"
            )
            if start_time >= end_time:
                raise ValueError("Group plan option end_time must be after start time.")

            plan_option_payloads.append(
                {
                    "label": str(option.get("label") or "").strip(),
                    "title": str(option.get("title") or "").strip(),
                    "description": str(option.get("description") or "").strip(),
                    "location": str(option.get("location") or "").strip(),
                    "start_time": start_time,
                    "end_time": end_time,
                }
            )

        with transaction.atomic():
            plan = GroupPlan.objects.create(
                family_group=target_group,
                created_by=approved_by,
                title=str(payload.get("title") or proposal.summary).strip()
                or proposal.summary,
                description=str(payload.get("description") or "").strip(),
                template=template,
                mode=mode,
                status="OPEN",
            )
            for option_payload in plan_option_payloads:
                GroupPlanOption.objects.create(plan=plan, **option_payload)

        return {
            "plan_id": str(plan.id),
            "group_id": str(target_group.id),
        }
