    <!-- Custom JS -->
    <script>
        // Auto-dismiss alerts after 5 seconds (skip error/warning for longer timeout)
        document.addEventListener('DOMContentLoaded', function () {
            setTimeout(function () {
                const alerts = document.querySelectorAll('.alert');
                alerts.forEach(function (alert) {
                    if (alert.classList.contains('alert-danger') || alert.classList.contains('alert-error') || alert.classList.contains('alert-warning')) {
                        return; // Skip error/warning alerts for now
                    }
                    alert.style.animation = 'slideOut 0.3s ease-in forwards';
                    setTimeout(() => alert.remove(), 300);
                });
            }, 5000);

            // Dismiss error/warning alerts after 8 seconds
            setTimeout(function () {
                const alerts = document.querySelectorAll('.alert-danger, .alert-error, .alert-warning');
                alerts.forEach(function (alert) {
                    alert.style.animation = 'slideOut 0.3s ease-in forwards';
                    setTimeout(() => alert.remove(), 300);
                });
            }, 8000);
        });

        // Add slideOut animation
        const style = document.createElement('style');
        style.textContent = `
            @keyframes slideOut {
                to {
                    transform: translateX(100%);
                    opacity: 0;
                }
            }
        `;
        document.head.appendChild(style);

        // Alert close button
        document.addEventListener('click', function (e) {
            if (e.target.classList.contains('btn-close')) {
                const alert = e.target.closest('.alert');
                if (alert) {
                    alert.style.animation = 'slideOut 0.3s ease-in forwards';
                    setTimeout(() => alert.remove(), 300);
                }
            }
        });

        // Make current nav item active
        document.addEventListener('DOMContentLoaded', function () {
            const currentPath = window.location.pathname;
            const navLinks = document.querySelectorAll('.navbar-nav .nav-link');

            navLinks.forEach(function (link) {
                const href = link.getAttribute('href');
                // Skip dropdown toggle links (href="#")
                if (href === '#') return;
                if (href === currentPath || (href !== '/' && currentPath.startsWith(href))) {
                    link.classList.add('active');
                }
            });

            if (currentPath.startsWith('/households/') || currentPath.startsWith('/groceries/') || currentPath.startsWith('/meals/')) {
                const homeToggle = document.querySelector('[data-nav-dropdown-toggle]');
                if (homeToggle) {
                    homeToggle.classList.add('active');
                }
            }
        });

        // Bootstrap navbar is now handled by Bootstrap's JavaScript

        // Family nav dropdown toggle
        const homeNavToggle = document.querySelector('[data-nav-dropdown-toggle]');
        const homeNavDropdown = document.getElementById('homeNavDropdown');

        homeNavToggle?.addEventListener('click', function (e) {
            e.preventDefault();
            e.stopPropagation();
            homeNavDropdown?.classList.toggle('show');
            // Close other dropdowns
            userDropdown?.classList.remove('show');
            notificationDropdown?.classList.remove('show');
        });

        // User dropdown toggle
        const userToggle = document.querySelector('[data-user-toggle]');
        const userDropdown = document.getElementById('userDropdownMenu');

        userToggle?.addEventListener('click', function (e) {
            e.preventDefault();
            e.stopPropagation();
            notificationDropdown?.classList.remove('show');
            homeNavDropdown?.classList.remove('show');
            userDropdown?.classList.toggle('show');
        });

        // Notification dropdown toggle
        const notificationToggle = document.querySelector('[data-notification-toggle]');
        const notificationDropdown = notificationToggle?.nextElementSibling;

        notificationToggle?.addEventListener('click', function (e) {
            e.preventDefault();
            e.stopPropagation();
            notificationDropdown?.classList.toggle('show');

            // Close other dropdowns
            userDropdown?.classList.remove('show');
            homeNavDropdown?.classList.remove('show');
        });

        // Close dropdowns when clicking outside
        document.addEventListener('click', function (e) {
            if (!e.target.closest('.dropdown')) {
                userDropdown?.classList.remove('show');
                notificationDropdown?.classList.remove('show');
                homeNavDropdown?.classList.remove('show');
            }
        });

        // Notification polling - update unread count every 60 seconds
        // Only poll if notification badge exists (authenticated users only)
        if (document.querySelector('.notification-badge')) {
            const notificationPollInterval = setInterval(function() {
                fetch('/notifications/api/notifications/unread_count/', {
                    credentials: 'same-origin',
                    headers: {'Accept': 'application/json'}
                })
                .then(response => {
                    if (!response.ok) {
                        if (response.status === 401 || response.status === 403) {
                            clearInterval(notificationPollInterval);
                        }
                        return null;
                    }
                    return response.json();
                })
                .then(data => {
                    if (!data) return;
                    const badge = document.querySelector('.notification-badge');
                    if (badge) {
                        const oldCount = parseInt(badge.textContent) || 0;
                        const newCount = data.count || 0;
                        if (newCount > 0) {
                            badge.textContent = newCount;
                            badge.style.display = 'flex';
                            if (newCount > oldCount) {
                                badge.classList.add('badge-bounce');
                                setTimeout(() => badge.classList.remove('badge-bounce'), 600);
                            }
                        } else {
                            badge.style.display = 'none';
                        }
                    }
                })
                .catch(() => {});
            }, 60000);
        }

        // Collapse functionality
        document.querySelectorAll('[data-bs-toggle="collapse"]').forEach(function (element) {
            element.addEventListener('click', function (e) {
                e.preventDefault();
                const targetSelector = this.getAttribute('data-bs-target');

                if (!targetSelector) return;

                const target = document.querySelector(targetSelector);

                if (target) {
                    target.classList.toggle('show');
                    const isExpanded = target.classList.contains('show');
                    this.setAttribute('aria-expanded', isExpanded);

                    // Update chevron icon if present
                    const chevron = this.querySelector('.bi-chevron-down, .bi-chevron-up');
                    if (chevron) {
                        if (isExpanded) {
                            chevron.classList.remove('bi-chevron-down');
                            chevron.classList.add('bi-chevron-up');
                        } else {
                            chevron.classList.remove('bi-chevron-up');
                            chevron.classList.add('bi-chevron-down');
                        }
                    }
                }
            });
        });

        // Handle family join key in URL parameters
        document.addEventListener('DOMContentLoaded', function () {
            // Function to get URL parameters
            function getUrlParameter(name) {
                name = name.replace(/[\[]/, '\\[').replace(/[\]]/, '\\]');
                var regex = new RegExp('[\\?&]' + name + '=([^&#]*)');
                var results = regex.exec(location.search);
                return results === null ? '' : decodeURIComponent(results[1].replace(/\+/g, ' '));
            }

            // Function to set a cookie
            function setCookie(name, value, days) {
                var expires = "";
                if (days) {
                    var date = new Date();
                    date.setTime(date.getTime() + (days * 24 * 60 * 60 * 1000));
                    expires = "; expires=" + date.toUTCString();
                }
                document.cookie = name + "=" + (value || "") + expires + "; path=/";
            }

            // Function to get a cookie
            function getCookie(name) {
                var nameEQ = name + "=";
                var ca = document.cookie.split(';');
                for (var i = 0; i < ca.length; i++) {
                    var c = ca[i];
                    while (c.charAt(0) == ' ') c = c.substring(1, c.length);
                    if (c.indexOf(nameEQ) == 0) return c.substring(nameEQ.length, c.length);
                }
                return null;
            }

            // Check for join_key parameter
            const joinKeyParam = getUrlParameter('join_key');
            if (joinKeyParam) {
                // Store the join key in a cookie for 1 day
                setCookie('family_join_key', joinKeyParam, 1);

                // Add join_key parameter to social auth links
                const socialAuthLinks = document.querySelectorAll('a[href*="accounts/google/login"], a[href*="accounts/facebook/login"]');
                socialAuthLinks.forEach(function (link) {
                    const href = link.getAttribute('href');
                    const separator = href.includes('?') ? '&' : '?';
                    link.setAttribute('href', href + separator + 'join_key=' + joinKeyParam);
                });
            } else {
                // Check if we have a stored join key in cookie
                const storedJoinKey = getCookie('family_join_key');
                if (storedJoinKey) {
                    // Add join_key parameter to social auth links
                    const socialAuthLinks = document.querySelectorAll('a[href*="accounts/google/login"], a[href*="accounts/facebook/login"]');
                    socialAuthLinks.forEach(function (link) {
                        const href = link.getAttribute('href');
                        const separator = href.includes('?') ? '&' : '?';
                        link.setAttribute('href', href + separator + 'join_key=' + storedJoinKey);
                    });
                }
            }
        });
    </script>

